-- Primary keys are UUIDv7 generated by the application (time-ordered, index-friendly).

create table users (
  id            uuid primary key,
  email         text not null,
  display_name  text not null,
  password_hash text not null,
  role          text not null check (role in ('user', 'admin')),
  created_at    timestamptz not null,
  updated_at    timestamptz not null,
  -- The application stores emails lower-cased; enforce it so uniqueness is case-insensitive.
  constraint users_email_lowercase check (email = lower(email)),
  constraint users_email_key unique (email)
);

create table refresh_tokens (
  id         uuid primary key,
  user_id    uuid not null references users (id) on delete cascade,
  family_id  uuid not null,
  token_hash text not null,
  expires_at timestamptz not null,
  revoked_at timestamptz,
  created_at timestamptz not null,
  constraint refresh_tokens_token_hash_key unique (token_hash)
);

create index refresh_tokens_user_id_idx on refresh_tokens (user_id);
create index refresh_tokens_family_id_idx on refresh_tokens (family_id);

create table days (
  id         uuid primary key,
  owner_id   uuid not null references users (id) on delete cascade,
  day_date   date not null,
  -- 0 means "not rated yet".
  rating     double precision not null check (rating between 0 and 10),
  journal    text not null,
  -- Check-ins are always read and replaced together with their day.
  emotions   jsonb not null,
  created_at timestamptz not null,
  updated_at timestamptz not null,
  -- One day per user per date; also serves the foreign key and date-range listings.
  constraint days_owner_id_day_date_key unique (owner_id, day_date)
);
